    ["Choose: The Stitcher or Spare Part Bindings\n7,040 XP • 45s • Undercity +150"] = {deDE = "Wählen Sie: The Stitcher oder Spare Part Bindings\n7.040 XP • 45 Sekunden • Unterstadt +150", frFR = "Choisissez : L'agrafeuse ou les reliures en pièces détachées\n7 040 XP • 45s • Fossoyeuse +150", esES = "Elija: La grapadora o las encuadernaciones de repuesto\n7,040 XP • 45s • Entrañas +150", itIT = "Scegli: la cucitrice o le rilegature per pezzi di ricambio\n7.040 XP • 45 secondi • Sepulcra +150", ptBR = "Escolha: o Stitcher ou as encadernações de peças sobressalentes\n7.040 XP • 45s • Cidade Baixa +150", ruRU = "Выбирайте: Сшиватель или Переплеты запасных частей.\n7040 опыта • 45 с • Подгород +150"},
