    ["Collect 10 Bloodied Insignias."] = {deDE = "Sammle 10 blutige Insignien.", frFR = "Récupérez 10 insignes ensanglantés.", esES = "Recoge 10 insignias ensangrentadas.", itIT = "Raccogli 10 insegne insanguinate.", ptBR = "Colete 10 Insígnias Ensanguentadas.", ruRU = "Соберите 10 окровавленных знаков различия."},
    ["Collect 10 Red Silk Bandanas from Defias inside the Deadmines."] = {deDE = "Sammle 10 rote Seidenbandanas von Defias in den Deadmines.", frFR = "Récupérez 10 bandanas en soie rouge auprès des Défias à l'intérieur des Mortemines.", esES = "Recoge 10 pañuelos de seda rojos de Defias dentro de Deadmines.", itIT = "Raccogli 10 bandane di seta rossa da Defias nelle Miniere della Morte.", ptBR = "Colete 10 Bandanas de Seda Vermelha de Défias dentro das Minas Mortas.", ruRU = "Соберите 10 красных шелковых бандан у Справедливости в Мертвых копях."},
    ["Collect 10 Serpentbloom from Wailing Caverns."] = {deDE = "Sammelt 10 Schlangenblüten aus den Höhlen der Klage.", frFR = "Récupérez 10 Serpentbloom dans les Grottes des Lamentations.", esES = "Recoge 10 flores de serpiente de las Cavernas de los Lamentos.", itIT = "Raccogli 10 fiori di serpente dalle caverne del pianto.", ptBR = "Colete 10 Serpentbloom nas Wailing Caverns.", ruRU = "Соберите 10 змеецветов в Пещерах Стенанья."},
    ["Collect 10 Twilight Pendants from Twilight's Hammer members in Blackfathom Deeps."] = {deDE = "Sammelt 10 Twilight-Anhänger von Twilight's Hammer-Mitgliedern in den Blackfathom Deeps.", frFR = "Récupérez 10 pendentifs du Crépuscule auprès des membres du Marteau du Crépuscule dans les Profondeurs de Fathom Noire.", esES = "Recoge 10 colgantes Crepusculares de los miembros del Martillo Crepuscular en Blackfathom Deeps.", itIT = "Raccogli 10 pendenti del Crepuscolo dai membri del Martello del Crepuscolo nelle Profondità di Blackfathom.", ptBR = "Colete 10 Pingentes do Crepúsculo dos membros do Martelo do Crepúsculo nas Profundezas Negras.", ruRU = "Соберите 10 сумеречных подвесок у членов Сумеречного Молота в Непроглядной Пучине."},
    ["Collect 20 Sapphires of Aku'Mai in Blackfathom Deeps."] = {deDE = "Sammle 20 Saphire von Aku'Mai in den Blackfathom Deeps.", frFR = "Récupérez 20 Saphirs d'Aku'Mai dans les Profondeurs de Fathom Noire.", esES = "Recoge 20 zafiros de Aku'Mai en Blackfathom Deeps.", itIT = "Raccogli 20 zaffiri di Aku'Mai nelle Profondità di Blackfathom.", ptBR = "Colete 20 Safiras de Aku'Mai nas Profundezas Negras.", ruRU = "Соберите 20 сапфиров Аку'мая в Непроглядной Пучине."},
    ["Collect 25 Intact Limbs within Ruins of Lordaeron."] = {deDE = "Sammle 25 intakte Gliedmaßen in den Ruinen von Lordaeron.", frFR = "Récupérez 25 membres intacts dans les ruines de Lordaeron.", esES = "Recoge 25 miembros intactos dentro de las ruinas de Lordaeron.", itIT = "Raccogli 25 arti intatti nelle Rovine di Lordaeron.", ptBR = "Colete 25 membros intactos nas Ruínas de Lordaeron.", ruRU = "Соберите 25 неповрежденных конечностей в руинах Лордерона."},
    ["Collect 4 Miners' Union Cards from undead miners in the tunnels outside the instance."] = {deDE = "Sammle 4 Bergmannsgewerkschaftskarten von untoten Bergleuten in den Tunneln außerhalb der Instanz.", frFR = "Récupérez 4 cartes Union des mineurs auprès des mineurs morts-vivants dans les tunnels à l'extérieur de l'instance.", esES = "Recoge 4 cartas del sindicato de mineros de los mineros no muertos en los túneles fuera de la instancia.", itIT = "Raccogli 4 carte dell'Unione dei minatori dai minatori non morti nei tunnel fuori dall'istanza.", ptBR = "Colete 4 Cartas de União de Mineiros de mineiros mortos-vivos nos túneis fora da instância.", ruRU = "Соберите 4 карты Союза горняков у шахтеров-нежити в туннелях за пределами инстанса."},
    ["Collect 8 Corrupted Brain Stems from creatures in Blackfathom Deeps."] = {deDE = "Sammle 8 verdorbene Hirnstämme von Kreaturen in den Blackfathom-Tiefen.", frFR = "Récupérez 8 troncs de cerveau corrompus sur des créatures des profondeurs de Blackfathom.", esES = "Recoge 8 troncos cerebrales corruptos de criaturas en Blackfathom Deeps.", itIT = "Raccogli 8 steli cerebrali corrotti dalle creature nelle Profondità di Blackfathom.", ptBR = "Colete 8 troncos cerebrais corrompidos de criaturas em Blackfathom Deeps.", ruRU = "Соберите 8 оскверненных стволов мозга у существ в Непроглядной Пучине."},
    ["Collect 8 Dwarven Heirlooms from the Hall of Thanes."] = {deDE = "Sammle 8 Zwergenerbstücke aus der Halle der Thanes.", frFR = "Récupérez 8 héritages nains dans la salle de Thanes.", esES = "Recoge 8 reliquias enanas del Salón de los Thanes.", itIT = "Raccogli 8 cimeli nanici dalla Sala dei Thanes.", ptBR = "Colete 8 Heranças Anãs do Salão dos Thanes.", ruRU = "Соберите 8 гномьих семейных реликвий в Зале Тана."},
    ["Collect Spells of Shadow and Incantations from the Nether inside Ragefire Chasm."] = {deDE = "Sammle Schattenzauber und Beschwörungsformeln aus dem Nether im Ragefire Chasm.", frFR = "Récupérez des sorts d'ombre et des incantations du Nether à l'intérieur du gouffre de Ragefire.", esES = "Recoge hechizos de sombras y encantamientos del abismo dentro de Ragefire Chasm.", itIT = "Raccogli incantesimi d'ombra e incantesimi dal Nether all'interno dell'Abisso di Fuocofuoco.", ptBR = "Colete feitiços de sombra e encantamentos do Nether dentro do Ragefire Chasm.", ruRU = "Соберите заклинания Тьмы и заклинания Пустоты в Огненной пропасти Ярости."},
    ["Collect the Head of the Baron in Ruins of Lordaeron."] = {deDE = "Sammeln Sie den Kopf des Barons in den Ruinen von Lordaeron.", frFR = "Récupérez la tête du baron dans les ruines de Lordaeron.", esES = "Recoge la cabeza del barón en las ruinas de Lordaeron.", itIT = "Raccogli la Testa del Barone nelle Rovine di Lordaeron.", ptBR = "Colete a Cabeça do Barão nas Ruínas de Lordaeron.", ruRU = "Соберите голову барона в руинах Лордерона."},
    ["Collect the Highly Toxic Strain from Witherfang."] = {deDE = "Sammelt den hochgiftigen Stamm von Witherfang.", frFR = "Récupérez la souche hautement toxique de Witherfang.", esES = "Recoge la cepa altamente tóxica de Witherfang.", itIT = "Raccogli la varietà altamente tossica da Zannabianca.", ptBR = "Colete a cepa altamente tóxica de Witherfang.", ruRU = "Заберите высокотоксичный штамм у Сухого Клыка."},
    ["Community reports indicate the Crest can spawn at one of several locations inside the dungeon. Reported spots include upper floors of towers, side/crypt rooms near The Baron, and the area around Bjork."] = {deDE = "Community-Berichten zufolge kann das Wappen an einer von mehreren Stellen im Dungeon erscheinen. Zu den gemeldeten Orten gehören obere Stockwerke von Türmen, Neben-/Grufträume in der Nähe des Barons und die Gegend um Björk.", frFR = "Les rapports de la communauté indiquent que le Crest peut apparaître à l'un des nombreux endroits du donjon. Les endroits signalés incluent les étages supérieurs des tours, les pièces latérales/cryptées près du Baron et la zone autour de Bjork.", esES = "Los informes de la comunidad indican que Crest puede aparecer en uno de varios lugares dentro de la mazmorra. Los lugares reportados incluyen pisos superiores de torres, salas laterales/criptas cerca de The Baron y el área alrededor de Bjork.", itIT = "I rapporti della community indicano che lo stemma può generarsi in una delle numerose posizioni all'interno del dungeon. I luoghi segnalati includono i piani superiori delle torri, stanze laterali/cripte vicino al Barone e l'area intorno a Bjork.", ptBR = "Relatórios da comunidade indicam que o Crest pode aparecer em um dos vários locais dentro da masmorra. Os locais relatados incluem andares superiores de torres, salas laterais/criptas perto do Barão e a área ao redor de Bjork.", ruRU = "В сообщениях сообщества указывается, что Герб может появиться в одном из нескольких мест внутри подземелья. Сообщается, что места обнаружения включают верхние этажи башен, боковые комнаты/крипты возле Барона и территорию вокруг Бьорка."},
    ["Crane Operator Bigglefuzz, Ratchet, The Barrens"] = {deDE = "Kranführer Bigglefuzz, Ratchet, The Barrens", frFR = "Grutier Bigglefuzz, Ratchet, The Barrens", esES = "Operador de grúa Bigglefuzz, Ratchet, The Barrens", itIT = "Operatore della gru Bigglefuzz, Ratchet, The Barrens", ptBR = "Operador de guindaste Bigglefuzz, Ratchet, The Barrens", ruRU = "Крановщик Бигглфазз, Рэтчет, Степи"},
    ["Dalar Dawnweaver, The Sepulcher, Silverpine Forest"] = {deDE = "Dalar Dawnweaver, Das Grab, Silberkiefernwald", frFR = "Dalar Tisse-aube, Le Sépulcre, Forêt des Pins Argentés", esES = "Dalar Tejedor del Alba, El Sepulcro, Bosque de Argénteos", itIT = "Dalar Dawnweaver, Il Sepolcro, Silverpine Forest", ptBR = "Dalar Dawnweaver, O Sepulcro, Floresta de Pinhaprata", ruRU = "Далар Ткач Зари, Гробница, Серебряный бор"},
    ["Dawnwatcher Selgorm, Darnassus"] = {deDE = "Dämmerungswächter Selgorm, Darnassus", frFR = "Veilleur de l'aube Selgorm, Darnassus", esES = "Vigilante del alba Selgorm, Darnassus", itIT = "Guardiano dell'Alba Selgorm, Darnassus", ptBR = "Vigilante da Alvorada Selgorm, Darnassus", ruRU = "Страж Рассвета Селгорм, Дарнас"},
