    ["Deathstalker Vincent, inside Shadowfang Keep"] = {deDE = "Todespirscher Vincent, in der Burg Schattenfang", frFR = "Le traqueur Vincent, à l'intérieur du donjon d'Ombrecroc", esES = "Deathstalker Vincent, dentro de Shadowfang Keep", itIT = "Vincent, l'inseguitore della morte, all'interno del Forte di Shadowfang", ptBR = "Deathstalker Vincent, dentro do Shadowfang Keep", ruRU = "Ловчий смерти Винсент, внутри крепости Темного Клыка."},
    ["Deep beneath the Barrens, druids and fanglords guard the sleeping Naralex while twisted beasts prowl the caverns."] = {deDE = "Tief unter dem Brachland bewachen Druiden und Fanglords den schlafenden Naralex, während verdorbene Bestien durch die Höhlen streifen.", frFR = "Au plus profond des Tarides, des druides et des fanglords gardent Naralex endormi tandis que des bêtes tordues rôdent dans les cavernes.", esES = "En lo profundo de Los Baldíos, druidas y señores de los colmillos protegen al dormido Naralex mientras bestias retorcidas merodean por las cavernas.", itIT = "Nelle profondità delle Savane, i druidi e i signori delle zanne sorvegliano il Naralex addormentato mentre bestie contorte si aggirano per le caverne.", ptBR = "Nas profundezas dos Sertões, druidas e senhores das presas guardam o adormecido Naralex enquanto feras retorcidas rondam as cavernas.", ruRU = "Глубоко под Степями друиды и повелители клыков охраняют спящего Наралекса, в то время как искажённые звери бродят по пещерам."},
    ["Defeat Edwin VanCleef and collect his head."] = {deDE = "Besiege Edwin VanCleef und sammle seinen Kopf.", frFR = "Battez Edwin VanCleef et récupérez sa tête.", esES = "Derrota a Edwin VanCleef y recoge su cabeza.", itIT = "Sconfiggi Edwin VanCleef e raccogli la sua testa.", ptBR = "Derrote Edwin VanCleef e pegue sua cabeça.", ruRU = "Победите Эдвина Ван Клифа и заберите его голову."},
    ["Defeat Lorgus Jett in Blackfathom Deeps."] = {deDE = "Besiege Lorgus Jett in den Blackfathom Deeps.", frFR = "Battez Lorgus Jett dans les Profondeurs de Fathom Noire.", esES = "Derrota a Lorgus Jett en las Abismos de Brazanegra.", itIT = "Sconfiggi Lorgus Jett nelle Profondità di Blackfathom.", ptBR = "Derrote Lorgus Jett nas Profundezas Negras.", ruRU = "Победите Лоргуса Джетта в Непроглядной Пучине."},
    ["Defeat Twilight Lord Kelris and recover the Head of Kelris."] = {deDE = "Besiege Twilight Lord Kelris und hol dir den Kopf von Kelris zurück.", frFR = "Battez Twilight Lord Kelris et récupérez la tête de Kelris.", esES = "Derrota a Twilight Lord Kelris y recupera la cabeza de Kelris.", itIT = "Sconfiggi il Signore del Crepuscolo Kelris e recupera la Testa di Kelris.", ptBR = "Derrote Lorde do Crepúsculo Kelris e recupere a Cabeça de Kelris.", ruRU = "Победите Сумеречного Лорда Келриса и верните голову Келриса."},
    ["Deliver the Abominable Head to the Undercity."] = {deDE = "Bringe den abscheulichen Kopf nach Unterstadt.", frFR = "Livrez la tête abominable à Fossoyeuse.", esES = "Entrega la cabeza abominable a Entrañas.", itIT = "Consegna la testa abominevole a Sepulcra.", ptBR = "Entregue a Cabeça Abominável na Cidade Baixa.", ruRU = "Доставьте отвратительную голову в Подгород."},
    ["Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge."] = {deDE = "Bringt den Vertrag der Verständigung zu Magni Bronzebeard in Ironforge.", frFR = "Remettez le Traité d'entente à Magni Barbe-de-Bronze à Forgefer.", esES = "Entrega el Tratado de Entendimiento a Magni Barbabronce en Forjaz.", itIT = "Consegna il Trattato d'Intesa a Magni Barbabronzea a Forgiardente.", ptBR = "Entregue o Tratado de Entendimento a Magni Barbabronze em Altaforja.", ruRU = "Доставьте Договор о взаимопонимании Магни Бронзобороду в Стальгорн."},
    ["Doan Karhan, The Barrens"] = {frFR = "Doan Karhan, Les Tarides", esES = "Doan Karhan, Los Baldíos", itIT = "Doan Karhan, Le Barrens", ptBR = "Doan Karhan, Os Sertões", ruRU = "Доан Кархан, «Степи»"},
    ["Earthseer Farsen, Dun Morogh (after Underground Map)"] = {deDE = "Erdseher Farsen, Dun Morogh (nach der Untergrundkarte)", frFR = "Earthseer Farsen, Dun Morogh (d'après la carte souterraine)", esES = "Vidente de la Tierra Farsen, Dun Morogh (después del mapa subterráneo)", itIT = "Veggente della Terra Farsen, Dun Morogh (dopo la mappa della metropolitana)", ptBR = "Earthseer Farsen, Dun Morogh (depois do mapa subterrâneo)", ruRU = "Землевидец Фарсен, Дун Морог (после карты подземелья)"},
    ["Ebru, above the entrance to Wailing Caverns, The Barrens"] = {deDE = "Ebru, über dem Eingang zu Wailing Caverns, The Barrens", frFR = "Ebru, au-dessus de l'entrée des Wailing Caverns, The Barrens", esES = "Ebru, encima de la entrada a las Cuevas de los Lamentos, Los Baldíos.", itIT = "Ebru, sopra l'ingresso delle Caverne del Pianto, The Barrens", ptBR = "Ebru, acima da entrada das Wailing Caverns, The Barrens", ruRU = "Эбру, над входом в Пещеры Плача, Степи."},
    ["Enter Hall of Thanes and claim Durgen Dirgehammer's Head."] = {deDE = "Betreten Sie die Halle der Thane und holen Sie sich den Kopf von Durgen Dirgehammer.", frFR = "Entrez dans le Hall de Thanes et récupérez la tête de Durgen Dirgehammer.", esES = "Ingresa al Salón de Thanes y reclama la cabeza de Durgen Dirgehammer.", itIT = "Entra nella Sala dei Thanes e reclama la Testa di Durgen Martello Funebre.", ptBR = "Entre no Hall of Thanes e reivindique a Cabeça de Durgen Dirgehammer.", ruRU = "Войдите в Зал Тана и заберите голову Дургена Киргимолота."},
    ["Final dungeon step of the Defias Brotherhood chain; complete the earlier steps first."] = {deDE = "Letzter Dungeon-Schritt der Defias-Bruderschaftskette; Führen Sie zunächst die vorherigen Schritte aus.", frFR = "Dernière étape du donjon de la chaîne Défias Brotherhood ; effectuez d'abord les étapes précédentes.", esES = "Paso final de mazmorra de la cadena Defias Brotherhood; Complete los pasos anteriores primero.", itIT = "Passo finale del dungeon della catena della Confraternita di Defias; completare prima i passaggi precedenti.", ptBR = "Etapa final da masmorra da cadeia da Irmandade Défias; conclua as etapas anteriores primeiro.", ruRU = "Последний этап подземелья в цепочке Братства Справедливости; сначала выполните предыдущие шаги."},
    ["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan."] = {deDE = "Findet 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan zurück.", frFR = "Trouvez 3 fragments de Soran'ruk et 1 grand fragment de Soran'ruk et rapportez-les à Doan Karhan.", esES = "Encuentra 3 fragmentos de Soran'ruk y 1 fragmento de Soran'ruk grande y devuélvelos a Doan Karhan.", itIT = "Trova 3 frammenti di Soran'ruk e 1 frammento di Soran'ruk grande e restituiscili a Doan Karhan.", ptBR = "Encontre 3 fragmentos de Soran'ruk e 1 fragmento grande de Soran'ruk e devolva-os para Doan Karhan.", ruRU = "Найдите 3 фрагмента Соран'рука и 1 большой фрагмент Соран'рука и верните их Доану Кархану."},
    ["Find Argent Guard Thaelrid inside Blackfathom Deeps."] = {deDE = "Findet den Argentumwächter Thaelrid in den Blackfathom Deeps.", frFR = "Trouvez le Garde d'Argent Thaelrid dans les Profondeurs de Fathom Noire.", esES = "Encuentra al guardia Argenta Thaelrid dentro de Blackbrathom Deeps.", itIT = "Trova la Guardia d'Argento Thaelrid nelle Profondità di Blackfathom.", ptBR = "Encontre o Guarda Argênteo Thaelrid nas Profundezas Negras.", ruRU = "Найдите Серебряного стража Талрида в Непроглядной Пучине."},
    ["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = {deDE = "Findet Todespirscher Adamant und Todespirscher Vincent in der Burg Schattenfang.", frFR = "Trouvez le Traqueur mortel Adamant et le Traqueur mortel Vincent dans le Donjon d'Ombrecroc.", esES = "Encuentra al Deathstalker Adamant y al Deathstalker Vincent dentro de Shadowfang Keep.", itIT = "Trova il Predatore della Morte Adamant e il Predatore della Morte Vincent all'interno del Forte di Zannambre.", ptBR = "Encontre Deathstalker Adamant e Deathstalker Vincent dentro do Shadowfang Keep.", ruRU = "Найдите Ловчего Смерти Адаманта и Ловчего Смерти Винсента в Крепости Темного Клыка."},
    ["Find Maur Grimtotem's corpse inside Ragefire Chasm and search it for anything of interest."] = {deDE = "Finden Sie Maur Grimtotems Leiche in Ragefire Chasm und durchsuchen Sie sie nach interessanten Dingen.", frFR = "Trouvez le cadavre de Maur Grimtotem dans le gouffre de Ragefire et recherchez-y tout ce qui vous intéresse.", esES = "Encuentra el cadáver de Maur Grimtotem dentro de Ragefire Chasm y búscalo en busca de algo de interés.", itIT = "Trova il cadavere di Maur Totemtruce all'interno dell'Abisso di Fuocofuoco e cerca qualcosa di interessante.", ptBR = "Encontre o cadáver de Maur Grimtotem dentro do Ragefire Chasm e procure por qualquer coisa de interesse.", ruRU = "Найдите труп Маура Зловещего Тотема в Огненной Пропасти Ярости и найдите в нем что-нибудь интересное."},
    ["Follow the quest directions beginning in Ratchet"] = {deDE = "Folgen Sie den Questanweisungen beginnend in Ratchet", frFR = "Suivez les instructions de la quête commençant à Ratchet.", esES = "Sigue las instrucciones de la misión que comienzan en Ratchet.", itIT = "Segui le indicazioni della missione che iniziano a Ratchet", ptBR = "Siga as instruções da missão começando em Ratchet", ruRU = "Следуйте указаниям квеста, начинающегося в Рэтчете."},
    ["Follows Speak with Shoni."] = {deDE = "Folgt „Sprechen mit Shoni“.", frFR = "Suit Parler avec Shoni.", esES = "Sigue Habla con Shoni.", itIT = "Segue Parla con Shoni.", ptBR = "Segue Fale com Shoni.", ruRU = "Следует за разговором с Шони."},
