    ["Item start: Blood-Stained Letter, graveyard inside Ruins of Lordaeron"] = {deDE = "Gegenstandsanfang: Blutbefleckter Brief, Friedhof in den Ruinen von Lordaeron", frFR = "Début de l'objet : Lettre tachée de sang, cimetière à l'intérieur des ruines de Lordaeron", esES = "Inicio del objeto: Carta manchada de sangre, cementerio dentro de las Ruinas de Lordaeron", itIT = "Inizio oggetto: Lettera macchiata di sangue, cimitero all'interno delle Rovine di Lordaeron", ptBR = "Início do item: Carta Manchada de Sangue, cemitério dentro das Ruínas de Lordaeron", ruRU = "Начало предмета: Окровавленное письмо, кладбище внутри Руин Лордерона."},
    ["Item start: Bloodied Insignia, inside Ruins of Lordaeron"] = {deDE = "Gegenstandsanfang: Blutige Insignien, in den Ruinen von Lordaeron", frFR = "Début de l'objet : Insigne ensanglanté, à l'intérieur des ruines de Lordaeron", esES = "Inicio del objeto: Insignia ensangrentada, dentro de las Ruinas de Lordaeron", itIT = "Inizio oggetto: Insegne insanguinate, all'interno delle Rovine di Lordaeron", ptBR = "Início do item: Bloodied Insignia, dentro das Ruínas de Lordaeron", ruRU = "Начало предмета: Окровавленный знак отличия, внутри Руин Лордерона."},
    ["Item start: Crest of Lordaeron, inside Ruins of Lordaeron"] = {deDE = "Gegenstandsanfang: Wappen von Lordaeron, in den Ruinen von Lordaeron", frFR = "Début de l'objet : Écusson de Lordaeron, à l'intérieur des ruines de Lordaeron", esES = "Inicio del artículo: Cresta de Lordaeron, dentro de las Ruinas de Lordaeron", itIT = "Inizio oggetto: Cresta di Lordaeron, all'interno delle Rovine di Lordaeron", ptBR = "Início do item: Crista de Lordaeron, dentro das Ruínas de Lordaeron", ruRU = "Начало предмета: Герб Лордерона, внутри Руин Лордерона."},
    ["Item start: Glowing Shard, dropped by Mutanus the Devourer"] = {deDE = "Artikelstart: Leuchtender Splitter, fallen gelassen von Mutanus dem Verschlinger", frFR = "Début de l'objet : Éclat lumineux, abandonné par Mutanus le Dévoreur", esES = "Inicio del objeto: fragmento resplandeciente, arrojado por Mutanus el Devorador", itIT = "Inizio oggetto: Frammento luminoso, droppato da Mutanus il Divoratore", ptBR = "Início do item: Fragmento Brilhante, largado por Mutanus, o Devorador", ruRU = "Начало предмета: Светящийся осколок, выпавший из Мутануса Пожирателя."},
    ["Item-start quest from the Blood-Stained Letter."] = {deDE = "Item-Start-Quest aus dem Blutbefleckten Brief.", frFR = "Quête de démarrage d'objet de la Lettre tachée de sang.", esES = "Misión de inicio del artículo de la Carta manchada de sangre.", itIT = "Quest iniziale con l'oggetto dalla Lettera macchiata di sangue.", ptBR = "Missão de início de item da Carta Manchada de Sangue.", ruRU = "Начало квеста с предмета «Окровавленное письмо»."},
    ["Je'neu Sancrea, Zoram'gar Outpost, Ashenvale"] = {deDE = "Je'neu Sancrea, Außenposten Zoram'gar, Ashenvale", frFR = "Je'neu Sancrea, avant-poste de Zoram'gar, Orneval", esES = "Je'neu Sancrea, puesto avanzado de Zoram'gar, Vallefresno", itIT = "Je'neu Sancrea, Avamposto di Zoram'gar, Valtetra", ptBR = "Je'neu Sancrea, posto avançado de Zoram'gar, Vale Gris", ruRU = "Дже'неу Санкреа, Застава Зорам'гар, Ясеневый лес"},
    ["Je'neu Sancrea, Zoram'gar Outpost, Ashenvale (12, 34)"] = {deDE = "Je'neu Sancrea, Außenposten Zoram'gar, Ashenvale (12, 34)", frFR = "Je'neu Sancrea, avant-poste de Zoram'gar, Orneval (12, 34)", esES = "Je'neu Sancrea, puesto avanzado de Zoram'gar, Vallefresno (12, 34)", itIT = "Je'neu Sancrea, Avamposto di Zoram'gar, Valtetra (12, 34)", ptBR = "Je'neu Sancrea, posto avançado de Zoram'gar, Ashenvale (12, 34)", ruRU = "Дже'неу Санкреа, Застава Зорам'гар, Ясеневый лес (12, 34)"},
    ["Keeper Bel'dugur, Apothecarium, Undercity"] = {deDE = "Hüter Bel'dugur, Apothecarium, Unterstadt", frFR = "Gardien Bel'dugur, Apothicaire, Fossoyeuse", esES = "Guardián Bel'dugur, Boticario, Entrañas", itIT = "Custode Bel'dugur, Farmacista, Sepulcra", ptBR = "Guardião Bel'dugur, Boticário, Cidade Baixa", ruRU = "Хранитель Бель'дугур, Апотекарий, Подгород"},
    ["Kill 15 Enraged Apparitions and 10 Tormented Souls, then put Anvilmar's spirit to rest."] = {deDE = "Töte 15 wütende Erscheinungen und 10 gequälte Seelen und beruhige dann Anvilmars Geist.", frFR = "Tuez 15 apparitions enragées et 10 âmes tourmentées, puis mettez au repos l'esprit d'Anvilmar.", esES = "Mata a 15 apariciones enfurecidas y a 10 almas atormentadas y luego haz descansar el espíritu de Anvilmar.", itIT = "Uccidi 15 Apparizioni Infuriate e 10 Anime Tormentate, poi metti a riposo lo spirito di Anvilmar.", ptBR = "Mate 15 Aparições Enfurecidas e 10 Almas Atormentadas e depois coloque o espírito de Anvilmar para descansar.", ruRU = "Убейте 15 разъяренных призраков и 10 измученных душ, а затем упокоите дух Наковальни."},
    ["Kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."] = {deDE = "Töte 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers und 7 Deviate Dreadfangs.", frFR = "Tuez 7 Ravageurs déviés, 7 Vipères déviées, 7 Shamblers déviés et 7 Crocs d'effroi déviés.", esES = "Mata a 7 devastadores desviados, 7 víboras desviados, 7 shamblers desviados y 7 colmillos aterradores desviados.", itIT = "Uccidi 7 Deviate Devastatori, 7 Deviate Vipers, 7 Deviate Shamblers e 7 Deviate Dreadfangs.", ptBR = "Mate 7 Devastadores Desviados, 7 Víboras Desviadas, 7 Shamblers Desviados e 7 Presas do Pavor Desviados.", ruRU = "Убейте 7 искажённых опустошителей, 7 искажённых гадюк, 7 искажённых шаркающих и 7 искажённых ужасных клыков."},
    ["Kill 8 Ragefire Troggs and 8 Ragefire Shamans inside Ragefire Chasm."] = {deDE = "Töte 8 Ragefire Troggs und 8 Ragefire Shamans im Ragefire Chasm.", frFR = "Tuez 8 Troggs Ragefire et 8 chamans Ragefire dans le gouffre Ragefire.", esES = "Mata a 8 troggs de Fuego Furioso y a 8 chamanes de Fuego Furioso dentro del Abismo de Fuego Furioso.", itIT = "Uccidi 8 Trogg di Fuoco Furioso e 8 Sciamani di Fuoco Furioso nell'Abisso di Fuoco Furioso.", ptBR = "Mate 8 Troggs Ragefire e 8 Ragefire Shamans dentro do Ragefire Chasm.", ruRU = "Убейте 8 троггов Яростного Огня и 8 шаманов Яростного Огня в Пропасти Яростного Огня."},
    ["Kill Archmage Arugal and bring his head to Dalar Dawnweaver."] = {deDE = "Tötet Erzmagier Arugal und bringt seinen Kopf zu Dalar Dawnweaver.", frFR = "Tuez l'archimage Arugal et apportez sa tête à Dalar Dawnweaver.", esES = "Mata al archimago Arugal y lleva su cabeza a Dalar Tejedor del Alba.", itIT = "Uccidi l'Arcimago Arugal e porta la sua testa a Dalar Dawnweaver.", ptBR = "Mate o Arquimago Arugal e leve sua cabeça para Dalar Dawnweaver.", ruRU = "Убейте верховного мага Аругала и принесите его голову Далару Ткачу Рассвета."},
    ["Kill Bazzalan and Jergosh the Invoker inside Ragefire Chasm."] = {deDE = "Tötet Bazzalan und Jergosh den Beschwörer im Ragefire Chasm.", frFR = "Tuez Bazzalan et Jergosh l'Invocateur dans le Gouffre de Ragefire.", esES = "Mata a Bazzalan y Jergosh the Invoker dentro de Ragefire Chasm.", itIT = "Uccidi Bazzalan e Jergosh l'Invocatore all'interno dell'Abisso di Fuocofuoco.", ptBR = "Mate Bazzalan e Jergosh, o Invocador, dentro do Ragefire Chasm.", ruRU = "Убейте Баззалана и Джергоша Призывателя в Огненной пропасти."},
    ["Kill Rath'mael in Ruins of Lordaeron."] = {deDE = "Tötet Rath'mael in den Ruinen von Lordaeron.", frFR = "Tuez Rath'mael dans les Ruines de Lordaeron.", esES = "Mata a Rath'mael en las Ruinas de Lordaeron.", itIT = "Uccidi Rath'mael alle Rovine di Lordaeron.", ptBR = "Mate Rath'mael nas Ruínas de Lordaeron.", ruRU = "Убейте Рат'маэля в Руинах Лордерона."},
    ["King Magni Bronzebeard, Ironforge"] = {deDE = "König Magni Bronzebart, Eisenschmiede", frFR = "Roi Magni Barbe-de-Bronze, Forgefer", esES = "Rey Magni Barbabronce, Forjaz", itIT = "Re Magni Barbabronzea, Forgiardente", ptBR = "Rei Magni Barbabronze, Altaforja", ruRU = "Король Магни Бронзобород, Стальгорн"},
    ["Lady Dena Kennedy, Stormwind City"] = {esES = "Lady Dena Kennedy, Ciudad de Ventormenta", itIT = "Lady Dena Kennedy, Città di Stormwind", ptBR = "Lady Dena Kennedy, Cidade de Ventobravo", ruRU = "Леди Дена Кеннеди, Штормград"},
    ["Master Apothecary Faranell, Undercity"] = {deDE = "Meisterapotheker Faranell, Unterstadt", frFR = "Maître Apothicaire Faranell, Fossoyeuse", esES = "Maestro boticario Faranell, Entrañas", itIT = "Maestro speziale Faranell, Sepulcra", ptBR = "Mestre Boticário Faranell, Cidade Baixa", ruRU = "Мастер-аптекарь Фаранелл, Подгород"},
    ["Maur Grimtotem's corpse inside Ragefire Chasm. From the first major three-way junction, take the right-hand tunnel, follow it uphill toward the dead end, then enter the small side room on the left. Interact with Maur's corpse there."] = {deDE = "Maur Grimtotems Leiche im Ragefire Chasm. Nehmen Sie von der ersten großen Drei-Wege-Kreuzung den rechten Tunnel, folgen Sie ihm bergauf in Richtung Sackgasse und betreten Sie dann den kleinen Nebenraum auf der linken Seite. Interagieren Sie dort mit Maurs Leiche.", frFR = "Cadavre de Maur Grimtotem à l'intérieur du gouffre de Ragefire. Depuis le premier grand carrefour à trois voies, prenez le tunnel de droite, suivez-le en montée jusqu'à l'impasse, puis entrez dans la petite pièce latérale sur la gauche. Interagissez avec le cadavre de Maur là-bas.", esES = "El cadáver de Maur Grimtotem dentro de Ragefire Chasm. Desde el primer cruce importante de tres vías, tome el túnel de la derecha, sígalo cuesta arriba hasta el callejón sin salida y luego entre en la pequeña habitación lateral de la izquierda. Interactúa con el cadáver de Maur allí.", itIT = "Il cadavere di Maur Totemtruce all'interno dell'Abisso di Fuocofuoco. Dal primo grande incrocio a tre, prendere il tunnel a destra, seguirlo in salita verso il vicolo cieco, quindi entrare nella piccola stanza laterale a sinistra. Interagisci lì con il cadavere di Maur.", ptBR = "O cadáver de Maur Grimtotem dentro do Ragefire Chasm. A partir do primeiro cruzamento principal de três vias, pegue o túnel da direita, siga subindo em direção ao beco sem saída e entre na pequena sala lateral à esquerda. Interaja com o cadáver de Maur lá.", ruRU = "Труп Маура Зловещего Тотема в Огненной Пропасти Ярости. От первого крупного трехстороннего перекрестка сверните в правый туннель, следуйте по нему в гору к тупику, затем войдите в небольшую боковую комнату слева. Взаимодействуйте там с трупом Маура."},
    ["Mebok Mizzyrix, Ratchet, The Barrens"] = {frFR = "Mebok Mizzyrix, Ratchet, Les Tarides", esES = "Mebok Mizzyrix, Ratchet, Los Baldíos", ruRU = "Мебок Миззирикс, Рэтчет, Степи"},
    ["Moonbrook, Westfall"] = {frFR = "Ruisseau de Lune, marche de l'Ouest", esES = "Moonbrook, Páramos de Poniente", itIT = "Moonbrook, Marche Occidentali", ruRU = "Мунбрук, Западный Край"},
    ["Morbin Lightbane, Undercity"] = {deDE = "Morbin Lightbane, Unterstadt", frFR = "Morbin Lightbane, Fossoyeuse", esES = "Morbin Aterraluz, Entrañas", itIT = "Morbin Sventura della Luce, Sepulcra", ptBR = "Morbin Lightbane, Cidade Baixa", ruRU = "Морбин Лайтбейн, Подгород"},
    ["Nalpak, above the entrance to Wailing Caverns, The Barrens"] = {deDE = "Nalpak, über dem Eingang zu Wailing Caverns, The Barrens", frFR = "Nalpak, au-dessus de l'entrée des Wailing Caverns, The Barrens", esES = "Nalpak, encima de la entrada a las Cuevas de los Lamentos, Los Baldíos.", itIT = "Nalpak, sopra l'ingresso delle Wailing Caverns, The Barrens", ptBR = "Nalpak, acima da entrada das Wailing Caverns, The Barrens", ruRU = "Налпак, над входом в Пещеры Плача, Степи."},
    ["Nara Wildmane, Thunder Bluff"] = {deDE = "Nara Wildmane, Donnerfels", frFR = "Nara Crinière Sauvage, Pitons du Tonnerre", esES = "Nara Melena Salvaje, Cima del Trueno", itIT = "Nara Mantoselvaggio, Picco del Tuono", ptBR = "Nara Juba Selvagem, Penhasco do Trovão", ruRU = "Нара Дикая Грива, Громовой Утес"},
    ["Neeru Fireblade, Cleft of Shadow, Orgrimmar"] = {deDE = "Neeru-Feuerklinge, Schattenspalte, Orgrimmar", frFR = "Neeru Fireblade, Faille de l'Ombre, Orgrimmar", esES = "Neeru Fireblade, Grieta de las Sombras, Orgrimmar", itIT = "Neeru Lama di Fuoco, Fenditura dell'Ombra, Orgrimmar", ptBR = "Neeru Lâmina de Fogo, Fenda das Sombras, Orgrimmar", ruRU = "Ниру Огненный Клинок, Расщелина Тени, Оргриммар"},
    ["Northern Barrens"] = {deDE = "Nördliches Brachland", frFR = "Tarides du Nord", esES = "Los Baldíos del Norte", itIT = "Savane settentrionali", ptBR = "Sertões do Norte", ruRU = "Северные Степи"},
    ["Optional quest-summoned encounter associated with the Fathom Stone; not part of the current 5-player seven-boss route."] = {deDE = "Optionale, durch eine Quest beschworene Begegnung im Zusammenhang mit dem Fathom Stone; nicht Teil der aktuellen 5-Spieler-Sieben-Boss-Route.", frFR = "Rencontre facultative invoquée par la quête associée à la Fathom Stone ; ne fait pas partie de la route actuelle à 5 joueurs et sept boss.", esES = "Encuentro opcional convocado por misión asociado con la Piedra Fathom; no forma parte de la ruta actual de 5 jugadores y siete jefes.", itIT = "Incontro facoltativo evocato da una missione associato alla Pietra Fathom; non fa parte dell'attuale percorso a sette boss da 5 giocatori.", ptBR = "Encontro opcional convocado por missão associado à Fathom Stone; não faz parte da rota atual de sete chefes para 5 jogadores.", ruRU = "Необязательная встреча, вызываемая квестом, связанная с Fathom Stone; не является частью текущего маршрута с семью боссами для 5 игроков."},
    ["Oran Snakewrithe, Undercity"] = {deDE = "Oran Snakewrithe, Unterstadt", frFR = "Oran Snakewrithe, Fossoyeuse", esES = "Oran Snakewrithe, Entrañas", itIT = "Oran Snakewrithe, Sepulcra", ptBR = "Oran Snakewrithe, Cidade Baixa", ruRU = "Оран Снейкрайт, Подгород"},
    ["Orphan Matron Nightingale, Stormwind City"] = {deDE = "Waisenmatrone Nightingale, Stadt Stormwind", frFR = "Matrone orpheline Nightingale, Stormwind City", esES = "Matrona huérfana Nightingale, Ciudad de Ventormenta", itIT = "Matrona Orfana Usignolo, Stormwind City", ptBR = "Órfã Matrona Nightingale, Cidade de Ventobravo", ruRU = "Попечительница сирот Найтингейл, Штормград"},
    ["Place the explosives beside the forge in the Deadmines."] = {deDE = "Platzieren Sie den Sprengstoff neben der Schmiede in den Deadmines.", frFR = "Placez les explosifs à côté de la forge dans les Mortemines.", esES = "Coloca los explosivos al lado de la fragua en Deadmines.", itIT = "Posiziona gli esplosivi accanto alla fucina nelle Deadmines.", ptBR = "Coloque os explosivos ao lado da forja nas Minas Mortas.", ruRU = "Поместите взрывчатку рядом с кузницей в Мертвых копях."},
    ["Put the spirit of Faldrim Anvilmar to rest."] = {deDE = "Beruhige den Geist von Faldrim Anvilmar.", frFR = "Mettez au repos l’esprit de Faldrim Anvilmar.", esES = "Haz descansar el espíritu de Faldrim Anvilmar.", itIT = "Metti a riposo lo spirito di Faldrim Anvilmar.", ptBR = "Coloque o espírito de Faldrim Anvilmar para descansar.", ruRU = "Упокоите дух Фалдрима Наковальни."},
    ["Rahauro, Elder Rise, Thunder Bluff"] = {esES = "Rahauro, Elder Rise, Cima del Trueno", itIT = "Rahauro, Ascesa Anziana, Picco del Tuono", ruRU = "Рахауро, Старший Райз, Громовой Утес"},
    ["Rare spawn in the side passage after Rhahk'Zor."] = {deDE = "Seltener Spawn im Seitengang nach Rhahk'Zor.", frFR = "Apparition rare dans le passage latéral après Rhahk'Zor.", esES = "Raro aparece en el pasaje lateral después de Rhahk'Zor.", itIT = "Spawn raro nel passaggio laterale dopo Rhahk'Zor.", ptBR = "Spawn raro na passagem lateral após Rhahk'Zor.", ruRU = "Редкое появление в боковом проходе после Рак'Зора."},
    ["Rare spawn."] = {deDE = "Seltene Brut.", frFR = "Apparition rare.", esES = "Raro engendro.", itIT = "Genere raro.", ptBR = "Geração rara.", ruRU = "Редкий спавн."},
    ["Recover Thistlenettle's Badge from Foreman Thistlenettle in the undead side tunnel."] = {deDE = "Holt Thistlenettles Abzeichen von Vorarbeiter Thistlenettle im Untoten-Seitentunnel zurück.", frFR = "Récupérez l'insigne de Thistlenettle auprès du contremaître Thistlenettle dans le tunnel latéral des morts-vivants.", esES = "Recupera la insignia de Thistlenettle del capataz Thistlenettle en el túnel lateral de los no-muertos.", itIT = "Recupera il distintivo di Thistlenettle dal caposquadra Thistlenettle nel tunnel laterale dei non morti.", ptBR = "Recupere a Insígnia de Thistlettle do Foreman Thistlettle no túnel lateral dos mortos-vivos.", ruRU = "Заберите значок Чертополоха у бригадира Чертополоха в боковом туннеле нежити."},
    ["Recover the Fathom Core from the Fathom Stone in Blackfathom Deeps."] = {deDE = "Holen Sie den Fathom-Kern aus dem Fathom-Stein in den Blackfathom-Tiefen zurück.", frFR = "Récupérez le noyau de Fathom sur la pierre de Fathom dans les profondeurs de Blackfathom.", esES = "Recupera el núcleo de Fathom de la piedra de Fathom en Blackfathom Deeps.", itIT = "Recupera il Nucleo di Fathom dalla Pietra di Fathom a Blackfathom Deeps.", ptBR = "Recupere o Fathom Core da Fathom Stone em Blackfathom Deeps.", ruRU = "Найдите Ядро Бездны из Камня Бездны в Непроглядной Пучине."},
    ["Recover the Gnoam Sprecklesprocket from Sneed's Shredder."] = {deDE = "Beschafft das Gnoam-Sprecklesrocket aus Sneeds Shredder.", frFR = "Récupérez le Gnoam Sprecklesprocket dans le Déchiqueteur de Sneed.", esES = "Recupera el Gnoam Sprecklesprocket de la trituradora de Sneed.", itIT = "Recupera lo Gnoam Sprecklesprocket dal Trituratore di Sneed.", ptBR = "Recupere o Gnoam Sprecklesprocket do Shredder de Sneed.", ruRU = "Заберите звездочку гноама из крошшера Снида."},
    ["Recover the Lorgalis Manuscript from Blackfathom Deeps."] = {deDE = "Holen Sie das Lorgalis-Manuskript aus den Blackfathom Deeps zurück.", frFR = "Récupérez le manuscrit de Lorgalis dans les profondeurs de Blackfathom.", esES = "Recupera el manuscrito de Lorgalis de Blackfathom Deeps.", itIT = "Recupera il manoscritto Lorgalis dalle Profondità di Blackfathom.", ptBR = "Recupere o Manuscrito de Lorgalis nas Profundezas Negras.", ruRU = "Найдите рукопись Лоргалис в Непроглядной Пучине."},
    ["Requires the Barrens oasis quest chain. Complete The Barrens Oases, The Forgotten Pools, The Stagnant Oasis and Altered Beings, then Hamuul Runetotem and Nara Wildmane before Leaders of the Fang becomes available."] = {deDE = "Erfordert die Questreihe „Barrens-Oase“. Schließe „The Barrens Oases“, „The Forgotten Pools“, „The Stagnant Oasis“ und „Altered Beings“ sowie „Hamuul Runetotem“ und „Nara Wildmane“ ab, bevor „Leaders of the Fang“ verfügbar wird.", frFR = "Nécessite la chaîne de quêtes de l'Oasis des Tarides. Terminez les oasis des Tarides, les bassins oubliés, l'oasis stagnante et les êtres modifiés, puis Hamuul Runetotem et Nara Wildmane avant que les dirigeants du Fang ne soient disponibles.", esES = "Requiere la cadena de misiones del oasis de Los Baldíos. Completa The Barrens Oasis, The Forgotten Pools, The Stagnant Oasis y Altered Beings, luego Hamuul Runetotem y Nara Wildmane antes de que Leaders of the Fang esté disponible.", itIT = "Richiede la catena di missioni dell'oasi di Barrens. Completa The Barrens Oases, The Forgotten Pools, The Stagnant Oasis e Altered Beings, poi Hamuul Runetotem e Nara Wildmane prima che Leaders of the Fang diventi disponibile.", ptBR = "Requer a cadeia de missões do oásis de Barrens. Conclua The Barrens Oases, The Forgotten Pools, The Stagnant Oasis e Altered Beings, depois Hamuul Runetotem e Nara Wildmane antes que Leaders of the Fang fique disponível.", ruRU = "Требуется цепочка квестов «Оазис Степи». Завершите задания «Оазисы Степи», «Забытые пруды», «Застойный оазис» и «Измененные существа», затем «Хамуул Рунный Тотем» и «Нара Дикая Грива», прежде чем станут доступны «Вожди Клыка»."},
    ["Requires the Defias Brotherhood escort step."] = {deDE = "Erfordert den Begleitschritt der Defias-Bruderschaft.", frFR = "Nécessite l'étape d'escorte de la Confrérie Défias.", esES = "Requiere el paso de escolta de la Hermandad Defias.", itIT = "Richiede il passaggio di scorta della Confraternita di Defias.", ptBR = "Requer a etapa de escolta da Irmandade Défias.", ruRU = "Требуется ступень сопровождения Братства Справедливости."},
    ["Requires the earlier Hidden Enemies chain steps in Orgrimmar. The next Hidden Enemies step later offers:"] = {deDE = "Erfordert die früheren Schritte der Hidden Enemies-Kette in Orgrimmar. Der nächste Hidden Enemies-Schritt später bietet:", frFR = "Nécessite les étapes précédentes de la chaîne Ennemis cachés à Orgrimmar. La prochaine étape Hidden Enemies propose plus tard :", esES = "Requiere los pasos anteriores de la cadena de Enemigos Ocultos en Orgrimmar. El siguiente paso de Enemigos ocultos ofrece:", itIT = "Richiede i precedenti passaggi della catena Nemici nascosti a Orgrimmar. Il passaggio successivo di Nemici nascosti offre:", ptBR = "Requer as etapas anteriores da cadeia de Inimigos Ocultos em Orgrimmar. A próxima etapa de Inimigos Ocultos oferece:", ruRU = "Требуются предыдущие этапы цепочки «Скрытые враги» в Оргриммаре. Следующий шаг Hidden Enemies предлагает:"},
    ["Retrieve the 99-Year-Old Port from Mad Magglish in Wailing Caverns."] = {deDE = "Holen Sie sich den 99 Jahre alten Hafen von Mad Magglish in den Wailing Caverns.", frFR = "Récupérez le porto vieux de 99 ans auprès de Mad Magglish dans les Wailing Caverns.", esES = "Recupera el puerto de 99 años de Mad Magglish en Wailing Caverns.", itIT = "Recupera il porto vecchio di 99 anni da Mad Magglish nelle Caverne dei Lamenti.", ptBR = "Recupere o Porto de 99 anos de Mad Magglish em Wailing Caverns.", ruRU = "Заберите портвейн 99-летней давности у Безумного Магглиша в Пещерах Стенанья."},
    ["Return the Crest of Lordaeron to Stormwind."] = {deDE = "Bringt das Wappen von Lordaeron nach Sturmwind zurück.", frFR = "Rapportez l'écusson de Lordaeron à Hurlevent.", esES = "Devuelve el escudo de Lordaeron a Ventormenta.", itIT = "Restituisci lo stemma di Lordaeron a Stormwind.", ptBR = "Devolva o brasão de Lordaeron para Ventobravo.", ruRU = "Верните герб Лордерона в Штормград."},
    ["Scourge forces still haunt the ruined capital while a necromancer gathers power within the city."] = {deDE = "Geißelkräfte suchen noch immer die zerstörte Hauptstadt heim, während ein Nekromant die Macht in der Stadt sammelt.", frFR = "Les forces du Fléau hantent toujours la capitale en ruine tandis qu'un nécromancien prend le pouvoir au sein de la ville.", esES = "Las fuerzas de la Plaga aún acechan la capital en ruinas mientras un nigromante gana poder dentro de la ciudad.", itIT = "Le forze del Flagello infestano ancora la capitale in rovina mentre un negromante prende il potere all'interno della città.", ptBR = "As forças do Flagelo ainda assombram a capital em ruínas enquanto um necromante reúne poder dentro da cidade.", ruRU = "Силы Плети все еще преследуют разрушенную столицу, пока некромант собирает власть в городе."},
    ["Scout Riell, Sentinel Hill tower, Westfall"] = {deDE = "Scout Riell, Sentinel Hill Tower, Westfall", frFR = "Scout Riell, tour Sentinel Hill, marche de l'Ouest", esES = "Explorador Riell, torre Sentinel Hill, Páramos de Poniente", itIT = "Scout Riell, torre di Sentinel Hill, Marche Occidentali", ptBR = "Scout Riell, torre Sentinel Hill, Westfall", ruRU = "Разведчик Риелл, башня Сторожевого холма, Западный Край"},
    ["Seal of Sylvanas\n14,355 XP • Undercity +200"] = {deDE = "Siegel von Sylvanas\n14.355 XP • Undercity +200", frFR = "Sceau de Sylvanas\n14 355 XP • Fossoyeuse +200", esES = "Sello de Sylvanas\n14,355 XP • Entrañas +200", itIT = "Sigillo di Sylvanas\n14.355 XP • Sepulcra +200", ptBR = "Selo de Sylvanas\n14.355 XP • Cidade Baixa +200", ruRU = "Печать Сильваны\n14 355 опыта • Подгород +200"},
    ["Shoni the Shilent, Stormwind"] = {deDE = "Shoni der Shilent, Sturmwind", frFR = "Shoni le Silencieux, Hurlevent", esES = "Shoni el Shilent, Ventormenta", itIT = "Shoni la Shilent, Stormwind", ptBR = "Shoni, o Shilent, Ventobravo", ruRU = "Шони Молчаливый, Штормград"},
    ["Shoni the Shilent, the Dwarven District, Stormwind"] = {deDE = "Shoni der Shilent, Zwergenbezirk, Sturmwind", frFR = "Shoni le Shilent, le quartier des nains, Hurlevent", esES = "Shoni el Shilent, el Distrito Enano, Ventormenta", itIT = "Shoni the Shilent, il Distretto dei Nani, Stormwind", ptBR = "Shoni, o Shilent, o Distrito dos Anões, Ventobravo", ruRU = "Шони Молчаливый, Квартал Гномов, Штормград."},
    ["Silverpine Forest"] = {deDE = "Silberkiefernwald", frFR = "Forêt des Pins Argentés", esES = "Bosque de Argénteos", itIT = "Foresta di pino argentato", ptBR = "Floresta de Pinhaprata", ruRU = "Серебряный бор"},
    ["Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart."] = {deDE = "Tötet Taragaman den Hungernden und erlangt das Herz von Taragaman dem Hungernden zurück.", frFR = "Tuez Taragaman l'Affameur et récupérez le cœur de Taragaman l'Affamé.", esES = "Mata a Taragaman el Hambre y recupera el corazón de Taragaman el Hambre.", itIT = "Uccidi Taragaman l'Affamato e recupera il Cuore di Taragaman l'Affamato.", ptBR = "Mate Taragaman, o Faminto, e recupere o Coração de Taragaman, o Faminto.", ruRU = "Убейте Тарагамана Голодного и добудьте Сердце Тарагамана Голодного."},
    ["Small Sack of Gems\n8,320 XP"] = {deDE = "Kleiner Sack voller Edelsteine\n8.320 XP", frFR = "Petit sac de pierres précieuses\n8 320 XP", esES = "Pequeño saco de gemas\n8,320 XP", itIT = "Piccolo sacco di gemme\n8.320 punti esperienza", ptBR = "Pequeno saco de joias\n8.320 XP", ruRU = "Маленький мешочек с драгоценными камнями\n8320 опыта"},
    ["Small Sack of Gems\n9,750 XP"] = {deDE = "Kleiner Sack voller Edelsteine\n9.750 XP", frFR = "Petit sac de pierres précieuses\n9 750 XP", esES = "Pequeño saco de gemas\n9.750 XP", itIT = "Piccolo sacco di gemme\n9.750 punti esperienza", ptBR = "Pequeno saco de joias\n9.750 XP", ruRU = "Маленький мешочек с драгоценными камнями\n9750 опыта"},
    ["Someone has broken into the royal dwarven burial chamber beneath Ironforge."] = {deDE = "Jemand ist in die Grabkammer der königlichen Zwerge unter Ironforge eingebrochen.", frFR = "Quelqu'un s'est introduit par effraction dans la chambre funéraire royale des nains située sous Forgefer.", esES = "Alguien ha irrumpido en la cámara funeraria real de los enanos debajo de Forjaz.", itIT = "Qualcuno è entrato nella camera funeraria reale dei nani sotto Forgiardente.", ptBR = "Alguém invadiu a câmara funerária real dos anões abaixo de Altaforja.", ruRU = "Кто-то проник в погребальную камеру королевских гномов под Стальгорном."},
    ["Speak to Je'neu Sancrea in Ashenvale."] = {deDE = "Sprecht mit Je'neu Sancrea in Ashenvale.", frFR = "Parlez à Je'neu Sancrea à Orneval.", esES = "Habla con Je'neu Sancrea en Vallefresno.", itIT = "Parla con Je'neu Sancrea a Valtetra.", ptBR = "Fale com Je'neu Sancrea em Ashenvale.", ruRU = "Поговорите с Дже'неу Санкреа в Ясеневом лесу."},
    ["Starts a follow-up chain that continues with Bazil Thredd."] = {deDE = "Startet eine Nachfolgekette, die mit Bazil Thredd fortgesetzt wird.", frFR = "Commence une chaîne de suivi qui se poursuit avec Bazil Thredd.", esES = "Inicia una cadena de seguimiento que continúa con Bazil Thredd.", itIT = "Inizia una catena successiva che continua con Bazil Thredd.", ptBR = "Inicia uma cadeia de acompanhamento que continua com Bazil Thredd.", ruRU = "Начинает цепочку последующих действий, которая продолжается Базилом Треддом."},
    ["Stone tablet inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = {deDE = "Steintafel in einem Gewölbe im Reliquiar der Könige (Dürgen Dirgehammers Zimmer)", frFR = "Tablette de pierre à l'intérieur d'une voûte du Reliquaire des Rois (chambre de Durgen Dirgehammer)", esES = "Tableta de piedra dentro de una bóveda en el Relicario de los Reyes (habitación de Durgen Dirgehammer)", itIT = "Tavoletta di pietra all'interno di una volta nel Reliquiario dei Re (stanza di Durgen Dirgehammer)", ptBR = "Placa de pedra dentro de um cofre no Relicário dos Reis (sala de Durgen Dirgehammer)", ruRU = "Каменная табличка в хранилище Реликвария королей (комната Дургена Киргехаммера)"},
    ["Tabitha Heartweaver, Silverpine Forest / The Sepulcher"] = {deDE = "Tabitha Heartweaver, Silverpine Forest / Das Grab", frFR = "Tabitha Heartweaver, Forêt des Pins Argentés / Le Sépulcre", esES = "Tabitha Tejecorazones, Bosque de Argénteos / El Sepulcro", itIT = "Tabitha Tessicuori, Foresta Pinargento / Il Sepolcro", ptBR = "Tabitha Heartweaver, Floresta Silverpine / O Sepulcro", ruRU = "Табита Хартвивер, Серебряный бор / Гробница"},
    ["Tabitha Heartweaver, The Sepulcher, Silverpine Forest"] = {deDE = "Tabitha Heartweaver, Das Grab, Silverpine Forest", frFR = "Tabitha Heartweaver, Le Sépulcre, Forêt des Pins Argentés", esES = "Tabitha Tejecorazones, El Sepulcro, Bosque de Argénteos", itIT = "Tabitha Tessicuori, Il Sepolcro, Foresta Pinargento", ptBR = "Tabitha Heartweaver, O Sepulcro, Floresta Silverpine", ruRU = "Табита Хартвивер, Гробница, Серебряный бор"},
    ["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = {deDE = "Bringt den Grimtotem-Rucksack zu Rahauro in Thunder Bluff.", frFR = "Apportez la sacoche Grimtotem à Rahauro à Thunder Bluff.", esES = "Lleva el Grimtotem Satchel a Rahauro en Thunder Bluff.", itIT = "Porta la Borsa del Totem Truce a Rahauro a Picco del Tuono.", ptBR = "Leve a Bolsa Grimtotem para Rahauro em Thunder Bluff.", ruRU = "Отнесите сумку Зловещего Тотема Рахауро в Громовой Утес."},
    ["Take the letter to the city architect in Stormwind."] = {deDE = "Bringt den Brief zum Stadtarchitekten in Sturmwind.", frFR = "Apportez la lettre à l'architecte de la ville de Hurlevent.", esES = "Lleva la carta al arquitecto de la ciudad en Ventormenta.", itIT = "Porta la lettera all'architetto della città a Stormwind.", ptBR = "Leve a carta ao arquiteto da cidade em Ventobravo.", ruRU = "Отнесите письмо городскому архитектору в Штормграде."},
    ["Tarnished Locket\n9,750 XP"] = {deDE = "Angelaufenes Medaillon\n9.750 XP", frFR = "Médaillon terni\n9 750 XP", esES = "Medallón deslustrado\n9.750 XP", itIT = "Medaglione appannato\n9.750 punti esperienza", ptBR = "Medalhão Manchado\n9.750 XP", ruRU = "Потускневший медальон\n9750 опыта"},
    ["The Defias Brotherhood is building a warship in the mines beneath Moonbrook."] = {deDE = "Die Defias-Bruderschaft baut in den Minen unterhalb von Moonbrook ein Kriegsschiff.", frFR = "La Confrérie Défias construit un navire de guerre dans les mines sous Moonbrook.", esES = "La Hermandad Defias está construyendo un buque de guerra en las minas debajo de Moonbrook.", itIT = "La Fratellanza Defias sta costruendo una nave da guerra nelle miniere sotto Moonbrook.", ptBR = "A Irmandade Défias está construindo um navio de guerra nas minas abaixo de Moonbrook.", ruRU = "Братство Справедливости строит военный корабль в шахтах под Мунбруком."},
    ["The Fathom Stone is also associated with the optional Baron Aquanis encounter."] = {deDE = "Der Fathom Stone ist auch mit der optionalen Begegnung mit Baron Aquanis verbunden.", frFR = "La Fathom Stone est également associée à la rencontre facultative du Baron Aquanis.", esES = "La Piedra Fathom también está asociada con el encuentro opcional con el Barón Aquanis.", itIT = "La Fathom Stone è anche associata all'incontro opzionale del Barone Aquanis.", ptBR = "A Fathom Stone também está associada ao encontro opcional do Barão Aquanis.", ruRU = "Камень глубин также связан с необязательной встречей с Бароном Акванисом."},
    ["The Lorgalis Manuscript is inside a Pitted Iron Chest underwater in the Pool of Ask'ar, in the northern alcove just past Ghamoo-ra's turtle room."] = {deDE = "Das Lorgalis-Manuskript befindet sich in einer eisenbedeckten Truhe unter Wasser im Teich von Ask'ar, in der nördlichen Nische direkt hinter Ghamoo-ras Schildkrötenraum.", frFR = "Le manuscrit de Lorgalis se trouve à l'intérieur d'un coffre de fer dénoyauté sous l'eau dans le bassin d'Ask'ar, dans l'alcôve nord juste après la salle des tortues de Ghamoo-ra.", esES = "El Manuscrito de Lorgalis se encuentra dentro de un cofre de hierro deshuesado bajo el agua en el estanque de Ask'ar, en el nicho norte, justo después de la sala de tortugas de Ghamoo-ra.", itIT = "Il Manoscritto Lorgalis si trova all'interno di una cassa di ferro bucherellata sott'acqua nella Piscina di Ask'ar, nell'alcova settentrionale appena oltre la stanza delle tartarughe di Ghamoo-ra.", ptBR = "O Manuscrito Lordalis está dentro de um baú de ferro perfurado debaixo d'água no Lago de Ask'ar, na alcova norte, logo após a sala das tartarugas de Ghamoo-ra.", ruRU = "Рукопись Лоргалис находится внутри железного сундука с ямками под водой в Пруде Аск'ар, в северной нише сразу за черепашьей комнатой Гаму-ра."},
    ["The chain begins by dropping Dark Iron Map from Dark Iron Spies in Dun Morogh."] = {deDE = "Die Kette beginnt mit der Abgabe einer Dunkeleisenkarte von Dunkeleisenspionen in Dun Morogh.", frFR = "La chaîne commence par l'obtention d'une carte Sombrefer auprès des Espions Sombrefer à Dun Morogh.", esES = "La cadena comienza lanzando Dark Iron Map de Dark Iron Spies en Dun Morogh.", itIT = "La catena inizia rilasciando la Mappa Ferroscuro dalle Spie Ferroscuro a Dun Morogh.", ptBR = "A cadeia começa com o Dark Iron Map dos Dark Iron Spies em Dun Morogh.", ruRU = "Цепочка начинается с получения Карты Черного Железа со Шпионов Черного Железа в Дун Мороге."},
    ["The current Forever quest data also lists Arcane Intellect as a learned reward."] = {deDE = "In den aktuellen Forever-Questdaten wird auch „Arkane Intelligenz“ als erlernte Belohnung aufgeführt.", frFR = "Les données actuelles de la quête Forever répertorient également Arcane Intellect comme récompense apprise.", esES = "Los datos actuales de la misión Forever también incluyen el intelecto arcano como recompensa aprendida.", itIT = "Gli attuali dati della missione Forever elencano anche l'Intelletto Arcano come ricompensa appresa.", ptBR = "Os dados atuais da missão Forever também listam o Intelecto Arcano como uma recompensa aprendida.", ruRU = "В текущих данных квеста «Навсегда» в качестве полученной награды также указан «Чародейский интеллект»."},
    ["The direct quest has no item reward. Its follow-up, In Nightmares, later offers:"] = {deDE = "Die direkte Quest hat keine Gegenstandsbelohnung. Sein Nachfolger, In Nightmares, bietet später:", frFR = "La quête directe n'a aucune récompense d'objet. Son suivi, In Nightmares, propose plus tard :", esES = "La misión directa no tiene recompensa de artículo. Su seguimiento, In Nightmares, ofrece más tarde:", itIT = "La missione diretta non prevede ricompense in oggetti. Il suo seguito, In Nightmares, offre in seguito:", ptBR = "A missão direta não tem recompensa de item. Sua continuação, In Nightmares, oferece posteriormente:", ruRU = "Прямой квест не имеет награды в виде предметов. Его продолжение, In Nightmares, позже предлагает:"},
    ["The foreman is in the tunnels before the instance portal."] = {deDE = "Der Vorarbeiter befindet sich in den Tunneln vor dem Instanzenportal.", frFR = "Le contremaître est dans les tunnels devant le portail de l'instance.", esES = "El capataz está en los túneles delante del portal de la instancia.", itIT = "Il caposquadra è nei tunnel prima del portale dell'istanza.", ptBR = "O capataz está nos túneis antes do portal da instância.", ruRU = "Бригадир находится в туннелях перед порталом инстанса."},
    ["The item choice is awarded on the follow-up Unending Torment step in Undercity."] = {deDE = "Die Gegenstandsauswahl wird im Folgeschritt „Unendliche Qual“ in Unterstadt vergeben.", frFR = "Le choix de l'objet est attribué lors de l'étape de suivi du Tourment sans fin à Fossoyeuse.", esES = "La elección del artículo se otorga en el siguiente paso de Tormento sin fin en Entrañas.", itIT = "L'oggetto scelto viene assegnato nella fase successiva del Tormento Infinito in Sepulcra.", ptBR = "A escolha do item é concedida na etapa subsequente Tormento Interminável em Cidade Baixa.", ruRU = "Выбор предмета предоставляется на следующем этапе «Бесконечные мучения» в Подгороде."},
    ["The ruined city of Lordaeron"] = {deDE = "Die zerstörte Stadt Lordaeron", frFR = "La ville en ruines de Lordaeron", esES = "La ciudad en ruinas de Lordaeron", itIT = "La città in rovina di Lordaeron", ptBR = "A cidade em ruínas de Lordaeron", ruRU = "Разрушенный город Лордерон"},
    ["The tablet is inside one of the vaults in the Reliquary of Kings, in Durgen Dirgehammer's final boss room. Open the vaults and interact with the tablet before leaving the dungeon."] = {deDE = "Die Tafel befindet sich in einem der Tresore im Reliquiar der Könige, in Durgen Dirgehammers letztem Bossraum. Öffne die Tresore und interagiere mit dem Tablet, bevor du den Kerker verlässt.", frFR = "La tablette se trouve à l'intérieur de l'un des coffres-forts du Reliquaire des Rois, dans la salle du boss final de Durgen Dirgehammer. Ouvrez les coffres-forts et interagissez avec la tablette avant de quitter le donjon.", esES = "La tableta está dentro de una de las bóvedas del Relicario de los Reyes, en la sala del jefe final de Durgen Dirgehammer. Abre las bóvedas e interactúa con la tableta antes de salir de la mazmorra.", itIT = "La tavoletta si trova all'interno di una delle cripte del Reliquiario dei Re, nella stanza del boss finale di Durgen Dirgehammer. Apri le casseforti e interagisci con il tablet prima di lasciare il sotterraneo.", ptBR = "O tablet está dentro de um dos cofres do Relicário dos Reis, na sala do chefe final de Durgen Dirgehammer. Abra os cofres e interaja com o tablet antes de sair da masmorra.", ruRU = "Табличка находится в одном из хранилищ Реликвария Королей, в комнате последнего босса Дургена Кровавого Молота. Откройте хранилища и взаимодействуйте с планшетом, прежде чем покинуть подземелье."},
    ["The undead side tunnel is before the instance portal."] = {deDE = "Der Untoten-Seitentunnel befindet sich vor dem Instanzportal.", frFR = "Le tunnel côté mort-vivant se trouve avant le portail de l'instance.", esES = "El túnel del lado de los no-muertos está antes del portal de la instancia.", itIT = "Il tunnel laterale dei non morti è prima del portale dell'istanza.", ptBR = "O túnel lateral dos mortos-vivos fica antes do portal da instância.", ruRU = "Боковой туннель нежити находится перед порталом инстанса."},
    ["Theodore Griffs, Undercity"] = {deDE = "Theodore Griffs, Unterstadt", frFR = "Théodore Griffs, Fossoyeuse", esES = "Theodore Griffs, Entrañas", itIT = "Theodore Griffs, Sepulcra", ptBR = "Theodore Griffs, Cidade Baixa", ruRU = "Теодор Гриффс, Подгород"},
    ["Thom Filch, by the bridge / vault entrance in Ironforge"] = {deDE = "Thom Filch, an der Brücke/Tresoreingang in Ironforge", frFR = "Thom Filch, près de l'entrée du pont / coffre-fort à Ironforge", esES = "Thom Filch, junto al puente/entrada de la bóveda en Ironforge", itIT = "Thom Filch, vicino all'ingresso del ponte/sepolcro a Forgiardente", ptBR = "Thom Filch, perto da entrada da ponte/cofre em Altaforja", ruRU = "Том Филч, у входа в мост/хранилище в Стальгорне."},
    ["Thom Filch, near the dungeon entrance"] = {deDE = "Thom Filch, in der Nähe des Kerkereingangs", frFR = "Thom Filch, près de l'entrée du donjon", esES = "Thom Filch, cerca de la entrada de la mazmorra.", itIT = "Thom Gazza, vicino all'ingresso del sotterraneo", ptBR = "Thom Filch, perto da entrada da masmorra", ruRU = "Том Филч, возле входа в подземелье"},
    ["Thrall, Valley of Wisdom, Orgrimmar"] = {deDE = "Thrall, Tal der Weisheit, Orgrimmar", frFR = "Thrall, Vallée de la Sagesse, Orgrimmar", esES = "Thrall, Valle de la Sabiduría, Orgrimmar", itIT = "Thrall, Valle della Saggezza, Orgrimmar", ptBR = "Thrall, Vale da Sabedoria, Orgrimmar", ruRU = "Тралл, Долина Мудрости, Оргриммар"},
    ["Travel to Ratchet to find someone who can identify the Glowing Shard, then deliver it as directed."] = {deDE = "Reisen Sie nach Ratchet, um jemanden zu finden, der den leuchtenden Splitter identifizieren kann, und liefern Sie ihn dann wie angewiesen ab.", frFR = "Rendez-vous à Ratchet pour trouver quelqu'un capable d'identifier l'éclat lumineux, puis livrez-le comme indiqué.", esES = "Viaja a Ratchet para encontrar a alguien que pueda identificar el fragmento resplandeciente y luego entrégalo según las instrucciones.", itIT = "Raggiungi Ratchet per trovare qualcuno che possa identificare il Frammento Luminoso, quindi consegnalo come indicato.", ptBR = "Viaje para Ratchet para encontrar alguém que possa identificar o Fragmento Brilhante e depois entregue-o conforme as instruções.", ruRU = "Отправляйтесь в Рэтчет, чтобы найти кого-нибудь, кто сможет идентифицировать светящийся осколок, а затем доставьте его, как указано."},
    ["Troggs and Burning Blade cultists infest the molten caverns beneath Orgrimmar."] = {deDE = "Troggs und Kultisten der Brennenden Klinge befallen die geschmolzenen Höhlen unter Orgrimmar.", frFR = "Les Troggs et les cultistes de Burning Blade infestent les cavernes en fusion sous Orgrimmar.", esES = "Los troggs y los cultistas de Burning Blade infestan las cavernas fundidas debajo de Orgrimmar.", itIT = "I cultisti Trogg e Lame Ardenti infestano le caverne fuse sotto Orgrimmar.", ptBR = "Os cultistas Troggs e Burning Blade infestam as cavernas derretidas abaixo de Orgrimmar.", ruRU = "Троггсы и культисты Пылающего Клинка наводняют расплавленные пещеры под Оргриммаром."},
