local overviewLanguages = {enUS = 1, enGB = 1, frFR = 2, esES = 3, esMX = 3, itIT = 4, ptBR = 5, ptPT = 5, ruRU = 6}
for original, translations in pairs(overviewText) do
    local row = displayText[original] or {}
    for code, column in pairs(overviewLanguages) do row[code] = translations[column] end
    displayText[original] = row
end

function C:LocalizeDisplay(value)
    if type(value) ~= "string" then return value end
    local translated = displayText[value]
    return translated and translated[self:GetLanguage()] or value
end

function C:LocalizeCatalog(value)
    if type(value) ~= "string" then return value end
    local translated = catalogText[value]
    return translated and translated[self:GetLanguage()] or value
end
